// TypeScript port of src/greekkv/memory/capacity.py.
//
// The planner recomputes capacity numbers in-browser so the UI stays
// snappy without a backend round trip. The port is intentionally tiny
// — it only covers the arithmetic actually used by the UI, not the
// measurement resolver (which the planner handles with the baked-in
// `data.json` snapshot).
//
// Parity with the Python implementation is asserted in capacity.test.ts
// against a hard-coded fixture generated by the Python module. If a
// future change diverges the two, that test is the place it will be
// caught before the UI prints a wrong number.

export type Scheme =
  | "fp16"
  | "int8-fakequant"
  | "int8-kivi"
  | "int4-fakequant"
  | "int4-kivi"
  | "eviction-sink";

export const ALL_SCHEMES: readonly Scheme[] = [
  "fp16",
  "int8-fakequant",
  "int8-kivi",
  "int4-fakequant",
  "int4-kivi",
  "eviction-sink",
];

export interface ArchConfig {
  num_hidden_layers: number;
  num_attention_heads: number;
  num_key_value_heads: number;
  hidden_size: number;
  head_dim?: number;
  num_parameters: number;
}

export interface SchemeSpec {
  bits_kv: number;
  group_size: number;
  residual_tokens: number;
  is_bounded: boolean;
}

export const DEFAULT_SCHEME_SPECS: Record<Scheme, SchemeSpec> = {
  "fp16":            { bits_kv: 16, group_size: 0,  residual_tokens: 0,  is_bounded: false },
  "int8-fakequant":  { bits_kv: 8,  group_size: 64, residual_tokens: 0,  is_bounded: false },
  "int8-kivi":       { bits_kv: 8,  group_size: 64, residual_tokens: 36, is_bounded: false },
  "int4-fakequant":  { bits_kv: 4,  group_size: 64, residual_tokens: 0,  is_bounded: false },
  "int4-kivi":       { bits_kv: 4,  group_size: 64, residual_tokens: 36, is_bounded: false },
  "eviction-sink":   { bits_kv: 16, group_size: 0,  residual_tokens: 36, is_bounded: true },
};

// 650 MiB — matches Python DEFAULT_OVERHEAD_BYTES.
export const DEFAULT_OVERHEAD_BYTES = 650 * 1024 * 1024;

// Scales are stored in FP16 (2 bytes) for every group-wise quantizer we
// consider. Mirror of greekkv.memory.kv.BYTES_PER_SCALE.
const BYTES_PER_SCALE = 2;

function headDim(cfg: ArchConfig): number {
  if (cfg.head_dim) return cfg.head_dim;
  if (cfg.hidden_size % cfg.num_attention_heads !== 0) {
    throw new Error(
      `hidden_size=${cfg.hidden_size} not divisible by num_attention_heads=${cfg.num_attention_heads}`,
    );
  }
  return cfg.hidden_size / cfg.num_attention_heads;
}

function quantOverheadBytes(
  nElems: number,
  bits: number,
  groupSize: number,
): number {
  if (bits >= 16 || groupSize <= 0) return 0;
  const nGroups = Math.ceil(nElems / groupSize);
  return nGroups * BYTES_PER_SCALE;
}

export function kvBytes(
  cfg: ArchConfig,
  nCtx: number,
  bits: number,
  groupSize: number,
): number {
  if (nCtx <= 0) return 0;
  const d = headDim(cfg);
  const perTensor = cfg.num_hidden_layers * cfg.num_key_value_heads * nCtx * d;
  const kvElems = 2 * perTensor;
  const dataBytes = (kvElems * bits) / 8;
  const overhead = quantOverheadBytes(kvElems, bits, groupSize);
  return Math.ceil(dataBytes + overhead);
}

export function weightsBytes(cfg: ArchConfig, bits: number = 16, groupSize: number = 0): number {
  const dataBytes = (cfg.num_parameters * bits) / 8;
  const overhead = quantOverheadBytes(cfg.num_parameters, bits, groupSize);
  return Math.ceil(dataBytes + overhead);
}

function kvForScheme(cfg: ArchConfig, nCtx: number, spec: SchemeSpec): number {
  if (nCtx === 0) return 0;
  if (spec.is_bounded) {
    const tokens = Math.min(nCtx, spec.residual_tokens);
    return kvBytes(cfg, tokens, 16, 0);
  }
  if (spec.residual_tokens > 0 && spec.bits_kv < 16) {
    const residual = Math.min(nCtx, spec.residual_tokens);
    const tail = Math.max(0, nCtx - residual);
    return kvBytes(cfg, residual, 16, 0) + kvBytes(cfg, tail, spec.bits_kv, spec.group_size);
  }
  return kvBytes(cfg, nCtx, spec.bits_kv, spec.group_size);
}

export interface CapacityRow {
  scheme: Scheme;
  n_ctx: number;
  weight_bytes: number;
  kv_bytes_per_user: number;
  overhead_bytes: number;
  free_bytes_after_weights: number;
  max_concurrent_users: number;
}

export interface CapacityInputs {
  cfg: ArchConfig;
  vram_bytes: number;
  n_ctx: number;
  scheme: Scheme;
  bits_weights?: number;
  weight_group_size?: number;
  overhead_bytes?: number;
}

export function capacity(inputs: CapacityInputs): CapacityRow {
  if (inputs.vram_bytes < 0) throw new Error(`vram_bytes must be non-negative, got ${inputs.vram_bytes}`);
  if (inputs.n_ctx < 0) throw new Error(`n_ctx must be non-negative, got ${inputs.n_ctx}`);

  const spec = DEFAULT_SCHEME_SPECS[inputs.scheme];
  if (!spec) throw new Error(`unknown scheme ${inputs.scheme}`);

  const wBytes = weightsBytes(
    inputs.cfg,
    inputs.bits_weights ?? 16,
    inputs.weight_group_size ?? 0,
  );
  const kvPerUser = kvForScheme(inputs.cfg, inputs.n_ctx, spec);
  const overhead = inputs.overhead_bytes ?? DEFAULT_OVERHEAD_BYTES;
  const free = inputs.vram_bytes - wBytes - overhead;
  const users = kvPerUser <= 0 || free <= 0 ? 0 : Math.floor(free / kvPerUser);

  return {
    scheme: inputs.scheme,
    n_ctx: inputs.n_ctx,
    weight_bytes: wBytes,
    kv_bytes_per_user: kvPerUser,
    overhead_bytes: overhead,
    free_bytes_after_weights: Math.max(0, free),
    max_concurrent_users: users,
  };
}

export function capacityGrid(
  cfg: ArchConfig,
  vramBytes: number,
  nCtx: number,
  overheadBytes: number = DEFAULT_OVERHEAD_BYTES,
): CapacityRow[] {
  return ALL_SCHEMES.map((scheme) =>
    capacity({ cfg, vram_bytes: vramBytes, n_ctx: nCtx, scheme, overhead_bytes: overheadBytes }),
  );
}
